effect.shader:
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 flakes = vec3(0.0);
    for(int i=1;i<=3;i++){
        float fi = float(i);
        float sc = 10.0*amount*fi + 6.0;
        vec2 g = acScreenNorm*vec2(sc, sc);
        g.y += acTime*speed*fi*0.8;
        g.x += sin(acTime*speed + fi)*0.5;
        vec2 id = floor(g);
        vec2 f = fract(g)-0.5;
        float h = rand(id+fi);
        float flake = smoothstep(0.18,0.0,length(f))*step(0.8,h);
        flakes += color.rgb*flake/fi;
    }
    gl_FragColor = src + vec4(flakes,0.0)*0.9;
}
